* Control Block for Simulations and Measurements
.control
  * 1. Operating Point: Measure Quiescent Power
  op
  let p_quiescent = -i(VDD) * 1.8
  print p_quiescent

  * 2. Transient Analysis: Slew Rate and Step Settling (Fig. 24.31)
  tran 0.1n 600n 0
  let vout_tran = v(Vout)
  meas tran sr_fall trig v(Vout) val=0.8 fall=1 targ v(Vout) val=0.2 fall=1
  let slew_rate_neg = (0.8 - 0.2) / sr_fall * 1e-6
  meas tran sr_rise trig v(Vout) val=0.2 rise=1 targ v(Vout) val=0.8 rise=1
  let slew_rate_pos = (0.8 - 0.2) / sr_rise * 1e-6
  print slew_rate_neg slew_rate_pos

  * 3. AC Open-Loop Analysis via Break Loop
  * Reconfigure sources dynamically for AC differential open-loop sweep
  alter Vin dc = 0.5 ac = 0
  alter Vref dc = 0.5 ac = 1
  * Alter feedback resistor to isolate AC loop while maintaining DC operating point
  alter R1 = 1e9
  ac dec 100 1 1G
  let gain_db = vdb(Vout)
  let phase_deg = 180 / PI * cph(v(Vout))
  meas ac open_loop_dc_gain find gain_db at=10
  meas ac fun when gain_db=0 fall=1
  meas ac phase_at_fun find phase_deg when gain_db=0 fall=1
  let phase_margin = 180 + phase_at_fun
  print open_loop_dc_gain fun phase_margin

  * 4. Common-Mode Rejection Ratio (CMRR)
  alter Vref ac = 1
  alter Vin ac = 1
  ac dec 50 1 100MEG
  let cm_gain_db = vdb(Vout)
  meas ac cm_gain_10 find cm_gain_db at=10
  let cmrr_val = open_loop_dc_gain - cm_gain_10
  print cmrr_val

  * 5. Power Supply Rejection Ratio (PSRR+)
  alter Vref ac = 0
  alter Vin ac = 0
  alter VDD ac = 1
  ac dec 50 1 100MEG
  let psrr_gain_db = vdb(Vout)
  meas ac psrr_gain_10 find psrr_gain_db at=10
  let psrr_pos_val = open_loop_dc_gain - psrr_gain_10
  print psrr_pos_val

  quit
.endc
.end

